test("T-AC-01 manages owner passkeys and signs out of the private console", async ({ page }) => {
  await page
    .getByRole("complementary", { name: "Barre latérale" })
    .getByRole("link", { name: "Réglages", exact: true })
    .click();
  await expect(page.getByRole("heading", { name: "Réglages", level: 1 })).toBeVisible();
  await expect(
    page.getByRole("heading", { name: "Accès propriétaire", exact: true }),
  ).toBeVisible();
  const keyPanel = page
    .getByRole("heading", { name: "Clés d’accès", exact: true })
    .locator("xpath=ancestor::section[1]");
  const revoke = keyPanel.getByRole("button", { name: "Révoquer", exact: true });
  await expect(revoke).toHaveCount(1);
  await expect(revoke).toBeDisabled();
  await expect(keyPanel.locator("[data-reason]")).toHaveAttribute(
    "title",
    /Dernière clé d’accès : ajoutez-en une autre/,
  );
  await keyPanel.getByLabel("Nom de la nouvelle clé").fill("Clé de secours USB");
  // A backup key belongs to another authenticator; the first device already has an excluded key.
  await enrolledAuthenticator.client.send("WebAuthn.setAutomaticPresenceSimulation", {
    authenticatorId: enrolledAuthenticator.authenticatorId,
    enabled: false,
  });
  await virtualOwnerAuthenticator(page, "usb");
  await page.getByRole("button", { name: "Ajouter une clé d’accès", exact: true }).click();
  await expect(revoke).toHaveCount(2);
  await expect(
    page.getByRole("status").filter({ hasText: "Votre nouvelle clé d’accès est enregistrée." }),
  ).toBeVisible();
  await expect(keyPanel.getByText("Clé de secours USB")).toBeVisible();
  await revoke.first().click();
  await expect(revoke).toHaveCount(1);
  await expect(revoke).toBeDisabled();
  await page.getByRole("button", { name: "Se déconnecter", exact: true }).click();
  await expect(
    page.getByRole("button", { name: "Se connecter avec une clé d’accès", exact: true }),
  ).toBeVisible();
  await expect(page.getByRole("navigation", { name: "Navigation principale" })).toHaveCount(0);
});

