// T-AC-06: real browser project and repository changes persist across reloads.
test("T33 registers, validates and reloads a project with its GitHub association", async ({
  page,
}) => {
  const name = `Projet e2e ${randomUUID().slice(0, 8)}`;
  const expectedSlug = name.toLowerCase().replaceAll(" ", "-");
  await page.goto("/");
  await page.getByRole("link", { name: "Nouveau projet", exact: true }).click();

  await expect(page).toHaveURL(/\/projects\/new$/);
  await page.getByLabel("Nom du projet", { exact: true }).fill(name);
  await expect(page.getByLabel("Identifiant", { exact: true })).toHaveValue(expectedSlug);
  await page.getByRole("radio", { name: /Site web/ }).check();
  await page.getByLabel(/Description/).fill("A browser-created local project fixture.");
  await page.getByRole("button", { name: "Enregistrer le projet", exact: true }).click();

  await expect(page).toHaveURL(/\/projects\/[a-f0-9-]{36}$/);
  await expect(page.getByRole("heading", { name, exact: true })).toBeVisible();
  const environments = page.getByRole("navigation", { name: "Environnement" });
  await expect(environments.getByRole("link", { name: "production" })).toBeVisible();
  await expect(environments.getByRole("link", { name: "development" })).toBeVisible();
  // Planned limits are shown as declared, never as measurements.
  await expect(page.getByText("plafond déclaré", { exact: true })).toHaveCount(3);
  await page.reload();
  await expect(page.getByRole("heading", { name, exact: true })).toBeVisible();

  await page.getByRole("button", { name: "Valider la configuration", exact: true }).click();
  await expect(
    page.getByRole("status").filter({ hasText: "Configuration locale validée" }),
  ).toHaveText("Configuration locale validée. Le projet n’a pas été provisionné.");
  await expect(page.getByText("Validé, non provisionné", { exact: true })).toBeVisible();

  await page
    .getByRole("navigation", { name: "Sections du projet" })
    .getByRole("link", { name: "Réglages" })
    .click();
  await expect(page.getByRole("heading", { name: "Production", exact: true })).toBeVisible();
  await expect(page.getByRole("heading", { name: "Développement", exact: true })).toBeVisible();
  await page.getByLabel("Dépôt", { exact: true }).fill("fixture/browser-project");
  await page.getByLabel("ID du dépôt", { exact: true }).fill("12345");
  await page.getByLabel("ID de l’installation GitHub App", { exact: true }).fill("67890");
  await page.getByLabel("Branche suivie", { exact: true }).fill("main");
  await page.getByRole("button", { name: "Enregistrer l’association", exact: true }).click();
  await expect(
    page.getByText("Association enregistrée localement.", { exact: true }),
  ).toBeVisible();

  await page.reload();
  await expect(page.getByLabel("Dépôt", { exact: true })).toHaveValue("fixture/browser-project");
  await expect(page.getByLabel("ID du dépôt", { exact: true })).toHaveValue("12345");
  await expect(page.getByLabel("ID de l’installation GitHub App", { exact: true })).toHaveValue(
    "67890",
  );
  await expect(page.getByLabel("Branche suivie", { exact: true })).toHaveValue("main");
  await expect(page.getByText("Validé, non provisionné", { exact: true })).toBeVisible();
});

